type LogoMarkProps = Omit<SVGProps<SVGSVGElement>, 'children' | 'viewBox'> & {
  title?: string
}

export function LogoMark({ className, title, ...props }: LogoMarkProps) {
  const hasAccessibleName = Boolean(title || props['aria-label'] || props['aria-labelledby'])
  const isAriaHidden = props['aria-hidden'] === true || props['aria-hidden'] === 'true'
  const isDecorative = isAriaHidden || !hasAccessibleName

  return (
    <svg
      {...props}
      aria-hidden={isDecorative ? true : undefined}
      className={cn('h-5 w-auto shrink-0 overflow-visible', className)}
      data-logo-mark=""
      fill="none"
      focusable="false"
      role={isDecorative ? undefined : 'img'}
      viewBox={MARK_VIEW_BOX}
      xmlns="http://www.w3.org/2000/svg"
    >
      {!isDecorative && title ? <title>{title}</title> : null}
      <path d={SHAPE_D} fill="none" stroke="currentColor" strokeLinecap="round" strokeWidth={6} />
    </svg>
  )
}

